import heapq

def match(orders):
    buy_heap = []  # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    book = {}  # id -> [side, price, qty, seq]
    trades = []
    seq_counter = 0

    def add_resting(oid, side, price, qty, seq):
        book[oid] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            seq_counter += 1
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            seq_counter += 1
            continue

        remaining = qty

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                if price is not None and top_price > price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting[2])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] == 0:
                    del book[top_id]
                    heapq.heappop(sell_heap)
                clean_sell()
        else:
            clean_buy()
            while remaining > 0 and buy_heap:
                negprice, top_seq, top_id = buy_heap[0]
                top_price = -negprice
                if price is not None and top_price < price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting[2])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] == 0:
                    del book[top_id]
                    heapq.heappop(buy_heap)
                clean_buy()

        if typ == 'limit' and remaining > 0:
            add_resting(oid, side, price, remaining, seq_counter)

        seq_counter += 1

    return trades

